<span class="line"><span style="color:#24292E;">  </span><span style="color:#005CC5;">&quot;method&quot;</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&quot;PUT&quot;</span><span style="color:#24292E;">,</span></span>
